{
"id": "explore",
"title": "Tokens spent by model",
"viz": "table",
"query": {
"sourceId": "eval-prometheus-demo",
"promql": "sum by (model) (increase(holotable_llm_tokens_total[1h]))",
"instant": true
},
"layout": {"x": 0, "y": 0, "w": 12, "h": 4},
"description": "Total LLM tokens consumed over the trailing hour, summed across instances, jobs, workspaces and directions, grouped by model.",
"format": "number",
"options": {
"columns": [
{"name": "model", "label": "Model"},
{"name": "value", "label": "Tokens", "format": "number", "compact": true, "align": "right"}
],
"sort": {"column": "value", "order": "desc"}
}
}
